create table "ddl_people" ("id" integer primary key autoincrement, "name" varchar(255) not null);
create table "ddl_kinds" ("kind_id" integer primary key autoincrement, "label" varchar(40) not null, "body" text not null, "count" integer not null, "big" integer not null, "ratio" real not null, "price" numeric(8, 2) not null, "exact" numeric(12, 4) not null, "flag" boolean not null, "meta" json not null, "token" uuid not null, "blob" blob not null, "day" date not null, "at" datetime not null);
create table "ddl_modifiers" ("id" uuid default (substr(printf('%012x', cast(unixepoch('subsec') * 1000 as integer)), 1, 8) || '-' || substr(printf('%012x', cast(unixepoch('subsec') * 1000 as integer)), 9, 4) || '-7' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (random() & 3), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))) primary key, "email" varchar(255) not null, "nickname" varchar(255), "role" varchar(255) default 'member' not null, "level" integer default 1 not null, "active" boolean default true not null, "settings" json default '{}' not null, "password" varchar(255) not null, "api_key" varchar(255), "public_id" uuid default (substr(printf('%012x', cast(unixepoch('subsec') * 1000 as integer)), 1, 8) || '-' || substr(printf('%012x', cast(unixepoch('subsec') * 1000 as integer)), 9, 4) || '-7' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (random() & 3), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))) not null, "seen_at" datetime default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), "created_at" datetime default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) not null, "updated_at" datetime default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) not null, "deleted_at" datetime);
create unique index "ddl_modifiers_email_unique" on "ddl_modifiers" ("email");
create unique index "ddl_modifiers_api_key_unique" on "ddl_modifiers" ("api_key");
create unique index "ddl_modifiers_public_id_unique" on "ddl_modifiers" ("public_id");
create table "ddl_categories" ("id" integer primary key autoincrement, "title" varchar(255) not null);
create table "ddl_codes" ("code" varchar(255) primary key, "title" varchar(255) not null);
create table "ddl_keys" ("id" integer primary key autoincrement, "person_id" integer not null references "ddl_people" ("id") on delete cascade, "editor_id" integer references "ddl_people" ("id") on delete set null, "owner_id" integer not null references "ddl_people" ("id") on delete restrict, "plain_id" integer not null references "ddl_people" ("id"), "modifier_id" uuid references "ddl_modifiers" ("id") on delete cascade, "loose_id" integer not null, "ddl_category_id" integer not null references "ddl_categories" ("id"));
